head.b:skin:
/* ============ روزنامچہ فاروقی — نجی ڈیش بورڈ تھیم ============
   رنگ:  اے آئی نیوز = گہرا نیلا + سنہری | Toolscape = گہرا سرمئی + فیروزی | نوائے فاروقی = زمردی + گہرا سنہری
   جس چینل کا صفحہ ہو، پورا رنگ اسی کا؛ پہلے صفحے پر تینوں کا امتزاج */
@font-face{font-family:'Jameel Noori Web';font-display:swap;
  src:local('Jameel Noori Nastaleeq'),local('JameelNooriNastaleeq'),
      url('https://cdn.jsdelivr.net/gh/abdulbasitfarooqi313-sys/farooqi-ai-news@main/fonts/jameel-noori.ttf') format('truetype')}
:root{
  --news:#0a1550; --news2:#e2b84f; --news-d:#050b33;
  --tools:#0e7490; --tools2:#22d3ee; --tools-d:#0b1220;
  --nawa:#1d5c46; --nawa2:#b08d3c; --nawa-d:#0f2f24;
  --a:var(--nawa); --a2:var(--nawa2); --ad:var(--nawa-d);
  --ink:#17201c; --muted:#5f6b66; --line:#e4e7e3; --bg:#f5f5f0; --card:#ffffff;
  --r:16px; --shadow:0 1px 2px rgba(16,30,25,.06),0 8px 28px rgba(16,30,25,.07);
  --ur:'Jameel Noori Web','Jameel Noori Nastaleeq','Noto Nastaliq Urdu',serif;
  --en:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif;
}
body.t-news{--a:var(--news);--a2:var(--news2);--ad:var(--news-d)}
body.t-tools{--a:var(--tools);--a2:var(--tools2);--ad:var(--tools-d)}
body.t-nawa{--a:var(--nawa);--a2:var(--nawa2);--ad:var(--nawa-d)}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--ur);font-size:18px;line-height:2.15;-webkit-font-smoothing:antialiased}
a{color:var(--a);text-decoration:none}
a:hover{text-decoration:underline}
.wrap{max-width:1080px;margin:0 auto;padding:0 16px}
.tri{height:5px;background:linear-gradient(90deg,var(--news) 0 22%,var(--news2) 22% 33%,var(--tools-d) 33% 55%,var(--tools2) 55% 66%,var(--nawa) 66% 88%,var(--nawa2) 88%)}
body.t-news .tri,body.t-tools .tri,body.t-nawa .tri{background:linear-gradient(90deg,var(--a) 0 70%,var(--a2) 70%)}

/* ---------- سرورق ---------- */
.top{color:#fff;position:relative;overflow:hidden;
  background:radial-gradient(1200px 400px at 85% -40%,rgba(255,255,255,.10),transparent 60%),
             linear-gradient(120deg,var(--news-d) 0%,var(--news) 30%,var(--tools-d) 50%,var(--nawa) 75%,var(--nawa-d) 100%)}
body.t-news .top,body.t-tools .top,body.t-nawa .top{
  background:radial-gradient(1000px 380px at 85% -40%,rgba(255,255,255,.12),transparent 60%),linear-gradient(120deg,var(--ad),var(--a))}
.top:before{content:'';position:absolute;inset:0;opacity:.07;
  background-image:repeating-linear-gradient(45deg,#fff 0 1px,transparent 1px 22px),repeating-linear-gradient(-45deg,#fff 0 1px,transparent 1px 22px)}
.top .wrap{position:relative;z-index:1;display:flex;align-items:center;justify-content:space-between;gap:18px;padding-top:26px;padding-bottom:22px}
.brand{display:flex;align-items:center;gap:16px}
.logo{width:84px;height:84px;border-radius:50%;flex:none;box-shadow:0 0 0 3px rgba(240,207,106,.55),0 10px 26px rgba(0,0,0,.35)}
.mark{width:60px;height:60px;border-radius:18px;flex:none;display:grid;place-items:center;position:relative;
  background:conic-gradient(from 200deg,var(--news2),var(--tools2),var(--nawa2),var(--news2));box-shadow:0 8px 22px rgba(0,0,0,.25)}
.mark span{width:50px;height:50px;border-radius:14px;background:var(--ad);display:grid;place-items:center;
  font-family:var(--ur);font-size:34px;line-height:50px;height:50px;color:var(--a2);text-align:center;padding:0 0 8px}
body:not(.t-news):not(.t-tools):not(.t-nawa) .mark span{background:#0d1f2e;color:#f0cf6a}
.brand h1{margin:0;font-size:32px;line-height:1.7;font-weight:700;letter-spacing:0}
.brand h1 a{color:#fff;text-decoration:none}
.brand p{margin:0;font-size:15px;opacity:.88;line-height:1.9}
.side{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.today{font-family:var(--en);font-size:12.5px;letter-spacing:.2px;background:rgba(255,255,255,.12);
  border:1px solid rgba(255,255,255,.22);padding:5px 14px;border-radius:999px;white-space:nowrap}
.badge{font-family:var(--en);font-size:11px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;color:var(--a2)}
body:not(.t-news):not(.t-tools):not(.t-nawa) .badge{color:#f0cf6a}

/* ---------- ٹیب ---------- */
.tabs{background:#fff;position:sticky;top:0;z-index:5;box-shadow:0 1px 0 var(--line),0 6px 18px rgba(0,0,0,.05)}
.tabs .wrap{display:flex;gap:6px;overflow-x:auto;padding-top:9px;padding-bottom:9px;scrollbar-width:none}
.tabs .wrap::-webkit-scrollbar{display:none}
.tabs a{color:var(--ink);padding:5px 16px;border-radius:999px;font-size:16px;white-space:nowrap;line-height:2;border:1px solid var(--line);background:#fff}
.tabs a:hover{text-decoration:none;border-color:var(--c,var(--a))}
.tabs a i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-inline-end:7px;vertical-align:middle;background:var(--c);box-shadow:0 0 0 3px color-mix(in srgb,var(--c) 18%,transparent)}
.tabs a.on{background:var(--c,var(--a));border-color:var(--c,var(--a));color:#fff}
.tabs a.on i{background:var(--c2,#fff);box-shadow:none}

/* ---------- فہرست ---------- */
main{padding:26px 0 46px}
.intro{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:24px}
.chan{border-radius:var(--r);padding:16px 18px 14px;color:#fff;display:block;position:relative;overflow:hidden;box-shadow:var(--shadow);
  background:linear-gradient(135deg,var(--cd),var(--c))}
.chan:after{content:'';position:absolute;inset:auto auto -30px -30px;width:110px;height:110px;border-radius:50%;border:10px solid var(--c2);opacity:.25}
.chan:hover{text-decoration:none;transform:translateY(-2px);transition:.15s}
.chan b{display:block;font-size:21px;line-height:1.8}
.chan span{font-size:14px;opacity:.9}
.chan em{font-style:normal;font-family:var(--en);font-size:11px;font-weight:800;letter-spacing:1.4px;color:var(--c2);text-transform:uppercase}
.sec-t{display:flex;align-items:center;gap:10px;margin:4px 0 12px;font-size:20px;color:var(--ad)}
.sec-t:after{content:'';flex:1;height:2px;background:linear-gradient(90deg,var(--a2),transparent)}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:16px}
.card{background:var(--card);border-radius:var(--r);box-shadow:var(--shadow);padding:16px 20px 16px;
  border-top:5px solid var(--c);display:flex;flex-direction:column;gap:4px;position:relative}
.card:before{content:'';position:absolute;top:-5px;inset-inline-start:0;width:30%;height:5px;background:var(--c2);border-start-start-radius:var(--r)}
.card h2{margin:0;font-size:20px;line-height:1.9}
.card h2 a{color:var(--ink)}
.meta{font-family:var(--en);font-size:12.5px;color:var(--muted);display:flex;gap:8px;flex-wrap:wrap;align-items:center;line-height:1.8}
.chip{display:inline-block;font-family:var(--en);font-size:12px;font-weight:700;padding:1px 11px;border-radius:999px;line-height:1.9;
  background:color-mix(in srgb,var(--c,var(--a)) 12%,#fff);color:var(--c,var(--a));border:1px solid color-mix(in srgb,var(--c,var(--a)) 25%,#fff)}
.snip{color:var(--muted);font-size:15.5px;margin:2px 0 8px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.more{margin-top:auto;font-weight:700;font-size:16px;color:var(--c)}
.pager{display:flex;justify-content:space-between;margin-top:26px}
.pager a{background:var(--card);box-shadow:var(--shadow);padding:5px 20px;border-radius:999px}
.empty{background:var(--card);border-radius:var(--r);padding:34px;text-align:center;color:var(--muted);box-shadow:var(--shadow)}

/* ---------- مکمل پوسٹ ---------- */
.single{background:var(--card);border-radius:var(--r);box-shadow:var(--shadow);overflow:hidden}
.single .head{padding:18px 26px 14px;background:linear-gradient(135deg,var(--ad),var(--a));color:#fff}
.single .head .meta{color:rgba(255,255,255,.8)}
.single .head .chip{background:rgba(255,255,255,.14);color:#fff;border-color:rgba(255,255,255,.25)}
.single h1{margin:0;font-size:27px;line-height:1.8}
.single .body{padding:10px 26px 30px}
.back{display:inline-block;margin:0 0 6px;font-size:15px;color:var(--a2)}

/* ---------- فوٹر ---------- */
footer{margin-top:10px;color:#cfd6d2;background:linear-gradient(120deg,#0b1220,#101b2a 45%,#0f2f24)}
body.t-news footer,body.t-tools footer,body.t-nawa footer{background:linear-gradient(120deg,var(--ad),#0b1220)}
.fgrid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:26px;padding:30px 0 18px}
footer .flogo{border-radius:50%;margin-bottom:6px;box-shadow:0 0 0 2px rgba(240,207,106,.4)}
footer h4{margin:0 0 8px;font-size:18px;color:#fff;font-weight:700;line-height:1.8}
footer p{margin:0;font-size:14.5px;line-height:2}
footer ul{list-style:none;margin:0;padding:0;font-size:15px;line-height:2.2}
footer a{color:#e9efe9}
footer li i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-inline-end:8px;vertical-align:middle;background:var(--c)}
.fbar{border-top:1px solid rgba(255,255,255,.1);padding:10px 0 16px;font-family:var(--en);font-size:12px;color:#9aa6a0;
  display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}

@media (max-width:760px){
  body{font-size:16.5px}
  .brand h1{font-size:24px}.logo{width:62px;height:62px}.mark{width:50px;height:50px}.mark span{width:41px;height:41px;font-size:28px;line-height:41px}
  .brand p{font-size:13px}.side{display:none}
  .intro{grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:18px}.grid{grid-template-columns:1fr}
  .chan{padding:10px 10px 8px;border-radius:12px;text-align:center}.chan:after{display:none}
  .chan b{font-size:15px;line-height:1.9}.chan span{display:none}.chan em{font-size:9px;letter-spacing:.6px}
  .single .head{padding:14px 16px}.single .body{padding:6px 12px 22px}.single h1{font-size:21px}
  .fgrid{grid-template-columns:1fr;gap:16px}
}

body.script:
//
(function(){
  var M={'AI News':'news','Toolscape':'tools','Nawa-e-Farooqi':'nawa'},
      N={news:['فاروقی اے آئی نیوز — روزانہ مواد مرکز','AI News Desk'],tools:['Toolscape — Daily content desk','Toolscape Desk'],nawa:['نوائے فاروقی — روزانہ مواد مرکز','Nawa-e-Farooqi Desk']},
      C={news:['#0a1550','#e2b84f'],tools:['#0e7490','#22d3ee'],nawa:['#1d5c46','#b08d3c']};
  var t=null, m=decodeURIComponent(location.pathname).match(/\/search\/label\/([^\/?]+)/);
  if(m&&M[m[1]])t=M[m[1]];
  if(!t&&document.querySelector('.single')){var c=document.querySelectorAll('.single .chip');for(var i=0;i<c.length;i++){if(M[c[i].getAttribute('data-l')]){t=M[c[i].getAttribute('data-l')];break;}}}
  if(t){document.body.className+=' t-'+t;
    var s=document.getElementById('sub'),b=document.getElementById('badge');if(s)s.textContent=N[t][0];if(b)b.textContent=N[t][1];
    var a=document.querySelectorAll('.tabs a');for(var j=0;j<a.length;j++){a[j].classList.toggle('on',a[j].getAttribute('data-t')===t);}
    var mc=document.querySelector('meta[name=theme-color]');if(mc)mc.setAttribute('content',C[t][0]);}
  var cs=document.querySelectorAll('.card');
  for(var k=0;k<cs.length;k++){var ch=cs[k].querySelectorAll('.chip'),tt='nawa';
    for(var q=0;q<ch.length;q++){if(M[ch[q].getAttribute('data-l')]){tt=M[ch[q].getAttribute('data-l')];break;}}
    cs[k].style.setProperty('--c',C[tt][0]);cs[k].style.setProperty('--c2',C[tt][1]);}
  var all=document.querySelectorAll('.chip');
  for(var z=0;z<all.length;z++){var l=M[all[z].getAttribute('data-l')];if(l)all[z].style.setProperty('--c',C[l][0]);}

  /* اگر Blogger کی فہرست خالی رہے تو پوسٹیں فیڈ سے لا کر خود دکھائیں */
  function L(e){var c=e.category||[];for(var i=0;i<c.length;i++){if(M[c[i].term])return c[i].term;}return 'Nawa-e-Farooqi';}
  function H(x){var d=document.createElement('div');d.textContent=x;return d.innerHTML;}
  function href(e){var l=e.link||[];for(var i=0;i<l.length;i++){if(l[i].rel==='alternate')return l[i].href;}return '#';}
  var box=document.getElementById('feedbox'),grid=document.querySelector('.grid');
  if(box&&!document.querySelector('.single')&&!(grid&&grid.querySelector('.card'))){
    var lab=m?m[1]:'',single=/\/\d{4}\/\d{2}\/.+\.html$/.test(location.pathname);
    fetch('/feeds/posts/default'+(lab&&!single?'/-/'+encodeURIComponent(lab):'')+'?alt=json&max-results=30',{credentials:'include'})
    .then(function(r){return r.json();}).then(function(j){
      var es=(j.feed&&j.feed.entry)||[],out='';
      if(single){
        for(var i=0;i<es.length;i++){var u=href(es[i]);if(u.split('?')[0].replace(/^https?:/,'')===location.href.split('?')[0].split('#')[0].replace(/^https?:/,'')){
          var lb=L(es[i]),tt=M[lb];document.body.className+=' t-'+tt;
          box.innerHTML="<article class='single'><div class='head'><a class='back' href='/'>→ واپس روزنامچہ</a><h1>"+H(es[i].title.$t)+"</h1><div class='meta'><span>"+es[i].published.$t.slice(0,10)+"</span><a class='chip' href='/search/label/"+encodeURIComponent(lb)+"'>"+H(lb)+"</a></div></div><div class='body'>"+es[i].content.$t+"</div></article>";
          var s2=document.getElementById('sub'),b2=document.getElementById('badge');if(s2)s2.textContent=N[tt][0];if(b2)b2.textContent=N[tt][1];return;}}
      }
      for(var k=0;k<es.length;k++){var e=es[k],lb2=L(e),c2=C[M[lb2]];
        out+="<article class='card' style='--c:"+c2[0]+";--c2:"+c2[1]+"'><h2><a href='"+href(e)+"'>"+H(e.title.$t)+"</a></h2><div class='meta'><span>"+e.published.$t.slice(0,10)+"</span><a class='chip' style='--c:"+c2[0]+"' href='/search/label/"+encodeURIComponent(lb2)+"'>"+H(lb2)+"</a></div><p class='snip'>آج کے ٹرینڈنگ موضوعات، تیار پیکج، مقابلین کا تجزیہ اور وائرل امکان</p><a class='more' href='"+href(e)+"'>پورا روزنامچہ کھولیں ←</a></article>";}
      box.innerHTML=out?"<div class='grid'>"+out+"</div>":"<div class='empty'>ابھی کوئی روزنامچہ نہیں — روز صبح 6 بجے نیا آتا ہے۔</div>";
    }).catch(function(){box.innerHTML="<div class='empty'>روزنامچے لوڈ نہ ہو سکے — صفحہ دوبارہ کھولیں۔</div>";});
  }
  try{document.getElementById('today').textContent=new Date().toLocaleDateString('ur-PK',{weekday:'long',day:'numeric',month:'long',year:'numeric'});}catch(e){}
})();
//
